INSERT INTO langs (Id, French) VALUES (9030000, 'Clef des Fers de la Tyrannie'),
 (9030001, 'Vous pouvez utiliser cette clef pour affronter Servitude, l''un des Cavaliers de l''Eliocalypse. Vous serez ainsi libéré du fardeau de la vie.'),
 (9030002, 'Plume de Misère'),
 (9030003, 'À force d''en vouloir toujours plus, on finit par y laisser des plumes...'),
 (9030004, 'Épaulière de Ferrailleur'),
 (9030005, 'Les Ferrailleurs sont particulièrement doués pour transformer la ferraille et autres détritus en armes ou en pièces d''armures, qui servent à équiper les armées de Misère. L''aspect très sommaire de ces équipements contraste avec leur étonnante solidité.'),
 (9030006, 'Langue de Krèvladal'),
 (9030007, 'Le moins qu''on puisse dire, c''est que les Krèvladals ont la langue bien pendue.'),
 (9030008, 'Côtes de Désosseur'),
 (9030009, 'Correctement préparées, les côtes de Désosseur ressembleront à s''y méprendre aux fameux travers de porkass sel-poivre dans leur version originale, d''ailleurs à ne pas confondre avec la version "Védouz". La viande est un peu maigre et c''est du cannibalisme, mais les saveurs sont au rendez-vous.'),
 (9030010, 'Capuche de Skentu'),
 (9030011, '"Un Skentu peut en cacher un autre". En effet, les Skentus, également surnommés "pillards du désert", ont développé la technique dite de la "Keuleuleu". Une technique qui consiste à se déplacer les uns derrière les autres afin de dissimuler leur nombre et ainsi surprendre leurs adversaires.'),
 (9030012, 'Œil de Dawaj'),
 (9030013, 'Ce que vous avez pris pour des yeux brillants sont en fait des pierres translucides, avec lesquelles les Dawajs se couvrent les yeux pour les protéger le jour et garder leur vue perçante la nuit.'),
 (9030014, 'Terre Stérile'),
 (9030015, 'Cette poignée de terre à la texture sablonneuse risque de ne pas faire un très bon engrais. C''est comme si tous les nutriments qu''elle contenait avaient été aspirés jusqu''au dernier.'),
 (9030016, 'Clef du Trône de Sang'),
 (9030017, 'Cette clef vous permettra de défier la plus sanguine des Cavaliers de l''Eliocalypse. N''oubliez pas de fourbir vos armes et de lustrer votre armure : quitte à être enterré par la hache de Guerre, autant ne pas ressembler à un mendiant.'),
 (9030018, 'Clef de l''Arbre de Mort'),
 (9030019, 'Pourriture, décrépitude et aliénation : tels sont les charmes de l''Arbre de Mort. Vous voulez retrouver vos racines et ne faire plus qu''un avec la nature ? Le Cavalier Corruption se fera une joie de vous transformer en compost.'),
 (9030020, 'Clef de la Sentence de la Balance'),
 (9030021, 'Il est presque impossible de s''entretenir avec Misère si ce n''est pas elle qui l''a décidé. Grâce à cette clef, vous parviendrez peut-être à lui forcer la main.'),
 (9030022, 'Convoitise de Misère'),
 (9030023, 'Perfide, calculatrice et manipulatrice : Misère a toujours un, deux, voire trois coups d''avance pour arriver à ses fins. Le mensonge est naturel pour elle, et son intelligence n''a d''égale que son avidité.'),
 (9030024, 'Solerets de Misère'),
 (9030025, '"Charognard, Pénurie
Charognard Gang
La Pénurie
Charognard, c''est charognard

À ce qu''il paraît
L''impôt a fait son temps, ils disent que des foutaises
Regarde nous on taxe encore
Le jour d''collecte
J''suis avec mon gang
On recompte les sommes, j''suis avec mon gang"


- Chanson écrite par Skani, le troubadour favori de Misère, afin de motiver les Collecteurs à taxer plus pour gagner moins.'),
 (9030026, 'Corset de Misère'),
 (9030027, 'Pour faire croire aux Miséreux qu''elle-même vit dans des conditions difficiles, mais surtout ne pas dépenser les innombrables ressources qu''elle accumule, Misère se nourrit très peu. C''est ce qui explique pourquoi elle est aussi squelettique.'),
 (9030028, 'Solerets de Guerre'),
 (9030029, 'Pour alimenter la Forgesang, les soldats de Guerre pressent des cadavres avec leurs pieds pour en extraire le sang nécessaire, à la manière du bon raisin de pays. Une pratique dans laquelle ils excellent, pour laquelle Guerre aura ces mots : « Ma dimension a du talent, mes légions ont du talon ».'),
 (9030030, 'Heaume de Guerre'),
 (9030031, '"La guerre est un jeu cruel qui ne se paie qu''avec le sang. Mais bon sang, qu''est-ce que c''est bon !" 

- Guerre'),
 (9030032, 'Forteresse de Guerre'),
 (9030033, 'D''après une rumeur qui court dans les rangs des Sanguinaires, le bouclier de Guerre serait une représentation de sa véritable apparence. Étonnement, personne n''a osé lui poser la question de vive voix.'),
 (9030034, 'Ceste de Guerre'),
 (9030035, 'À chacun sa manière de se faire respecter. Pour Guerre : une main de fer dans un gant de fer. Pour vous, une main de velours dans un gant trop lourd.'),
 (9030036, 'Écharpe de Servitude'),
 (9030037, 'Nul n''a jamais pu voir entièrement le visage de Servitude à cause de son écharpe. Peut-être a-t-il peur de s''enrhumer, ou bien cherche-t-il à dissimuler un menton en forme de postérieur qui nuirait à sa crédibilité.'),
 (9030038, 'Manteau de Servitude'),
 (9030039, 'Quand on a trop d''esclaves, on finit par ne plus savoir quoi en faire. Pour les occuper, Servitude a assigné pas moins de 100 prisonniers à l''entretien de sa précieuse cape, toute trace ou éraflure infligée à celle-ci étant bien sûr puni de mort. Autant dire qu''elle est impeccable en toutes circonstances.'),
 (9030040, 'Dora de Servitude'),
 (9030041, '"Toi qui rêvais de grands espaces et n''as eu que des fenêtres : aimerais-tu renaître, et déserter ces rangs d''esclaves ? Bien sûr que oui, mais tu peux toujours rêver ! Ou pas, mouahahaha ! "

- Servitude, se moquant de l''un de ses esclaves.'),
 (9030042, 'Germes corrompus'),
 (9030043, 'Un bouquet de ces germes pourrait vous attirer de mauvaises comme de fabuleuses fréquentations. Tout dépend de votre degré... d''ouverture.'),
 (9030044, 'Corne de Corruption'),
 (9030045, 'Il faut être brave pour endurer ses épines mais, tant qu''à être corrompu, autant y aller franchement.'),
 (9030046, 'Bague de Corruption'),
 (9030047, 'Cette bague a été forgée par les Sadidas corrompus en l''honneur de Corruption, pour lui signifier leur allégeance et leur dévotion. Un alliage spécial de leur conception permet à la bague de ne pas pourrir au contact de la peau hautement toxique du Cavalier.'),
 (9030048, 'Alliance de Corruption'),
 (9030049, 'Même si cela peut sembler être une bonne idée, évitez d''offrir cette alliance à votre promis ou votre promise. En effet, Corruption l''a fabriquée lui-même à partir de l''Arbre de Mort : dans le genre cadeau empoisonné, on fait difficilement mieux.'),
 (9030050, 'Langue de Pistilangue'),
 (9030051, 'Les aventuriers sont toujours en quête de trésors mais franchement... était-il nécessaire de récupérer la langue d''un Pistilangue ?'),
 (9030052, 'Peau pourrie de Dolid'),
 (9030053, 'Pour le plaisir ou par folie, chevaucher un Dolid est un exercice périlleux. Comme pour de nombreuses activités, la maîtrise vient en pratiquant et s''étirant pour ne pas se blesser. Œil pour œil, dent pour dent, cette peau déchirée est un symbole de vengeance.'),
 (9030054, 'Ceinturonce de Corruption'),
 (9030055, 'Comme le dit un obscur proverbe, "Il faut se méfier de la Corruption qui ne dort que d''un œil dans les orties de mémé". Personne n''en a jamais réellement compris le sens, mais dans le doute, méfiez-vous des grand-mères.'),
 (9030056, 'Patte de Nheur''Gueule'),
 (9030057, 'Il est vraiment déconseillé de demander la papatte à un Nheur''Gueule. Premièrement c''est un monstre sauvage qui ne pense probablement qu''à vous réduire en miette. Deuxièmement, parce que les poches de venin situées dans ses pattes vous feraient agoniser jusqu''à votre mort. De charmantes créatures ces bêtes-là.'),
 (9030058, 'Tentacule de Tentaclaque'),
 (9030059, 'Comme leur nom le laisse entendre, les Tentaclaques sont des monstres exaspérants. Ce tentacule est l''arme idéale pour leur faire comprendre la douleur qu''ils infligent aux autres par leur simple présence.'),
 (9030060, 'Pétale de Gangredogue'),
 (9030061, 'Faîtes attention à n''avoir arraché que le pétale du Gangredogue. Les spores qui pourraient y être attachés sont porteurs des pires maladies qu''il est possible d''imaginer. À voir votre visage, on se dit qu''il est peut-être déjà trop tard...'),
 (9030062, 'Bois de pagaie usée'),
 (9030063, 'Du bois tellement abîmé qu''il devait probablement servir aux galériens depuis des années.'),
 (9030064, 'Capuche d''Armécréante'),
 (9030065, 'Quand on passe sa vie sur un bateau, il vaut mieux se protéger de la météo.'),
 (9030066, 'Baguette Rythmique'),
 (9030067, 'Utile pour donner du rythme dans une galère, cette baguette peut aussi blesser si on la reçoit dans l''œil.'),
 (9030068, 'Verrou de Servitude'),
 (9030069, 'Personne n''a jamais pu forcer ce verrou, tout ceux qui l''ont porté ont servi leur maître jusqu''à leur dernier souffle.'),
 (9030070, 'Collier d''esclave'),
 (9030071, 'Quiconque porte ce collier se voit dépourvu de toute volonté de rébellion. Il est le symbole de la persécution dans un monde d''obéissance.'),
 (9030072, 'Boulet lesté'),
 (9030073, 'Ce boulet est extrêmement lourd, celui qui le traîne doit redoubler de vigilance s''il ne veut pas perdre un orteil.'),
 (9030074, 'Manche de Fouet'),
 (9030075, 'Un manche très ergonomique qui permet de fouetter plus fort pour augmenter le rendement.'),
 (9030076, 'Bonnet de Guerre'),
 (9030077, 'Certains le mettront sur la tête, d''autres mettront leur tête dedans. En bon érudit, vous avez tout de suite compris que cet objet ferait une parfaite genouillère.'),
 (9030078, 'Étoffe sanglante'),
 (9030079, 'Cette étoffe provient d''une cape qui a beaucoup trop traîné dans le sang et la poussière.'),
 (9030080, 'Sang coagulé'),
 (9030081, 'Ce sang provient d''une plaie ouverte qui ne date pas d''hier.'),
 (9030082, 'Canine tranchante'),
 (9030083, 'Tout le fer contenu dans le sang, s''est imprégné dans cette dent et l''a rendue aussi solide qu''une lame.'),
 (9030084, 'Fragment d''armure'),
 (9030085, 'Ce fragment provenant d''une armure titanesque semble avoir été forgé dans le sang.'),
 (9030086, 'Linothorax'),
 (9030087, 'Cette armure semble parfaite pour protéger les articulations du porteur lorsqu''il doit faire des mouvements amples.'),
 (9030088, 'Lame tranchante'),
 (9030089, 'Le nombre de têtes tranchées par cette lame pourrait faire tourner la vôtre.'),
 (9030090, 'Dofus du Cauchemar'),
 (9030091, '« Si la nuit est noire, c''est pour que rien ne puisse nous distraire de nos cauchemars » : tels étaient les mots du jeune Kilvan avant qu''il ne s''endorme, rassuré par son chtigre en peluche.
Pourquoi la nuit est-elle si sombre ? Parce qu''elle cache en son sein toutes les craintes, et tous les mystères, de l''éternuitée. Peurs bleues, braises rouges et glyphes mordorés se fondent et se confondent dans le berceau du bien et du mal, source d''un conflit éternellement renouvelé.'),
 (9030092, 'Panoplie de Misère'),
 (9030093, 'Panoplie de Guerre'),
 (9030094, 'Panoplie de Servitude'),
 (9030095, 'Panoplie de Corruption');
